basicCode.vanilla:
import { createContextBreakdown } from '@/components/ui/context-breakdown';

createContextBreakdown({
  parts: parcelas,
  labels: rotulos,
});

withLabelsCode.web:
// O que está sendo repartido, o que está sendo contado, e a palavra de cada
// origem — por ENDEREÇO, porque o endereço é o que a medição carrega e a
// palavra é interface.
//
// Origem sem palavra não some da lista: a linha mostra o próprio endereço, para
// que a cor nunca fique sozinha dizendo de qual parcela se trata.
const rotulos = {
  title: 'De onde veio o contexto',
  unit: 'tokens',
  parts: {
    system: 'Instruções do sistema',
    history: 'Histórico da conversa',
    attachments: 'Anexos',
    tools: 'Resultados de ferramenta',
  },
};

extensibilityCode.web:
// O DENOMINADOR É O TOTAL REPARTIDO, e nunca um teto. Esta repartição não pede
// teto nenhum para existir — é o que a separa da medição da janela:
contextTotal([{ id: 'a', tokens: 250 }, { id: 'b', tokens: 750 }]);   // 1000
contextSlices([{ id: 'a', tokens: 250 }, { id: 'b', tokens: 750 }]);  // 25% e 75%

// A ORDEM É A DE QUEM MEDIU, e não a do tamanho:
contextSlices([{ id: 'a', tokens: 1 }, { id: 'b', tokens: 99 }])
  .map((fatia) => fatia.id);                                          // ['a', 'b']

// A PARCELA ZERADA CONTINUA NA LISTA, para que a cor não escorregue de linha:
contextSlices([{ id: 'a', tokens: 100 }, { id: 'b', tokens: 0 }])
  .length;                                                            // 2

// E o por cento é TEXTO, travado nas duas pontas, porque é ele que se lê em voz:
contextSlices([{ id: 'a', tokens: 9999 }, { id: 'b', tokens: 1 }])
  .map((fatia) => fatia.percent);                                     // [99, 1]

// Sem nada repartido, tudo sai em zero — nunca em conta indefinida:
contextSlices([{ id: 'a', tokens: 0 }]).map((fatia) => fatia.percent); // [0]

customizationCode.web:
.nds-context-breakdown {
  max-inline-size: 24rem;
}

/* A cor é REFORÇO, e não a pista: o nome e o número de cada parcela estão em
   texto na legenda. Trocar a paleta não muda o que chega a quem ouve. */
.nds-context-breakdown-slice:nth-child(8n + 1),
.nds-context-breakdown-part:nth-child(8n + 1) {
  --nds-context-slice-color: var(--chart-5);
}

